import {laundryState} from './laundry-motion.js?v=motion-v70';
export const warDefaults={warEnabled:true,warLivingClouds:true,warCloudEvolution:.10,warCloudWind:12,warCloudDetail:.23,warCoverTime:1.2,warDarkTime:.8,warSkyTime:1.7,warRiseTime:1.6,warHold:2.5,warScale:1,warX:0,warY:0,warTravel:270,warCloudOpacity:1,warFireOpacity:.5,warFireEnabled:true,warCloudColor:'#d1d4d3',warFrontX:625,warFrontY:540,warFrontHeight:440,warFrontTravel:270,warFrontBlur:0,warRearX:130,warRearY:570,warRearHeight:300,warRearTravel:219,warRearBlur:2,warLandY:150,warLandTravel:177,warSkyTravel:60,warSkyScale:1.12,warSunX:850,warSunY:330,warSunRadius:280,warSunOpacity:.65,warFireTop:380,warFireHeight:160,warFireGlow:.12,warCloudDrift:12,warCloudScale:1};
const clamp=q=>Math.max(0,Math.min(1,q)),ease=q=>{q=clamp(q);return q*q*(3-2*q)};
export function warState(t,input={}){const f={...warDefaults,...input},start=laundryState(t,f).end,age=t-start,coverTime=Math.max(.1,f.warCoverTime),darkTime=Math.max(.1,f.warDarkTime),skyTime=Math.max(.1,f.warSkyTime),riseTime=Math.max(.1,f.warRiseTime),skyAt=coverTime+darkTime,riseAt=skyAt+skyTime,end=start+riseAt+riseTime+Math.max(0,f.warHold),distance=1640*ease(age/Math.max(.1,riseAt)),cloudProgress=distance<=740?distance/740:1+(distance-740)/900;return {cloudProgress,start,age,skyAt,riseAt,end,cover:ease(age/coverTime),sky:ease((age-skyAt)/skyTime),rise:ease((age-riseAt)/riseTime),active:f.warEnabled&&age>=0,fire:ease((age-riseAt)/Math.max(.1,riseTime))}}
